var meta_data = data.meta_data;
if (meta_data && typeof meta_data === 'string') {
    try {
        const parsed = JSON.parse(meta_data);
        if (Array.isArray(parsed.references)) {
            data.references = parsed.references;
        }
    } catch (e) {
        console.warn('Invalid meta_data JSON format, skipping references assignment', e);
    }
}
